<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('form.party-form');if(!form)return;const select=form.querySelector('select[name="currency_ids[]"]');const rows=form.querySelectorAll('[data-currency]');function sync(){const selected=new Set(Array.from(select.selectedOptions).map(o=>o.value));rows.forEach(row=>{const active=selected.has(row.dataset.currency);row.hidden=!active;row.querySelector('input').disabled=!active;});}select.addEventListener('change',sync);if(window.jQuery)window.jQuery(select).on('change',sync);sync();});</script>
